-- The review agent (jobs/product-monitor, T052.6) now writes one overall review per product,
-- generated by an AI model from every review it has collected for that product.
--
-- agent_review_summaries becomes the home for those. What it held until now, each source page's
-- own average rating and review count, moves to agent_source_ratings.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'agent_review_summaries'
          AND column_name = 'source'
    ) THEN
        ALTER TABLE agent_review_summaries RENAME TO agent_source_ratings;
        ALTER INDEX agent_review_summaries_pkey RENAME TO agent_source_ratings_pkey;
    END IF;
END $$;

-- One row per product, replaced when the product has reviews the model hasn't seen yet.
CREATE TABLE IF NOT EXISTS agent_review_summaries (
    product VARCHAR(100) PRIMARY KEY,
    product_name VARCHAR(200),
    overall_review TEXT NOT NULL CHECK (btrim(overall_review) <> ''),
    -- How many agent_reviews rows the product had when this was written, which is how the agent
    -- tells that there are new ones.
    review_count INTEGER NOT NULL CHECK (review_count >= 0),
    -- Which model wrote it, since this is AI-generated text.
    model VARCHAR(100) NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- As with the other tables: Supabase exposes public tables through its REST API, so with row level
-- security on and no policies, only the backend and the agent can read or change them.
ALTER TABLE agent_review_summaries ENABLE ROW LEVEL SECURITY;
